    data = {'@context':'https://schema.org','@type':'WebSite','name':'The Cipher Librarian','url':ORIGIN,'author':{'@type':'Person','name':'Paul Clark','alternateName':'The Cipher Librarian','url':ORIGIN+'/about/','sameAs':['https://systemslibrarian.dev/','https://github.com/systemslibrarian','https://www.linkedin.com/in/systemslibrarian']}}
