BOOK_CARD = f'''<article class="book-feature"><a class="shelf-cover" href="/books/secrets-of-the-cipher-museum/" aria-label="Discover Secrets of the Cipher Museum">{cover(small=True)}</a><div class="book-copy"><p class="eyebrow"><span class="status-dot"></span> Forthcoming · Narrative history</p><h3><a href="/books/secrets-of-the-cipher-museum/">Secrets of the<br>Cipher Museum</a></h3><p class="book-subtitle">Stories of Hidden Messages<br>and the People Behind Them</p><p>Follow twenty true investigations, then trace an intercepted letter’s route or compare two readings in the free museum.</p><a class="text-link" href="/books/secrets-of-the-cipher-museum/">Step inside the book {arrow()}</a></div><dl class="book-notes"><div><dt>20</dt><dd>investigations through history</dd></div><div><dt>For the curious</dt><dd>No mathematical background needed</dd></div><div><dt>Read, then explore</dt><dd>A free interactive museum alongside the book</dd></div></dl></article>'''

HOME = f'''<section class="hero wrap"><div class="hero-copy"><p class="eyebrow">Author · Librarian · Cryptography educator</p><h1>Every secret<br>has a <em>story.</em></h1><p class="hero-name">Paul Clark <span>— The Cipher Librarian</span></p><p class="hero-tagline">Exploring cryptography, from historical ciphers to post-quantum security.</p><div class="actions"><a class="button" href="/books/secrets-of-the-cipher-museum/">Discover the book {arrow()}</a><a class="text-link" href="/about/">Meet Paul {arrow()}</a></div></div><div class="hero-stage"><div class="stage-label"><span>On the reading desk</span><span>№ 01</span></div><div class="stage-dial" aria-hidden="true"></div><a class="hero-book" href="/books/secrets-of-the-cipher-museum/" aria-label="Explore Secrets of the Cipher Museum">{cover(eager=True)}</a><div class="stage-caption"><span class="caption-rule"></span><div><span>Secrets of the Cipher Museum</span><small>A forthcoming book by Paul Clark</small></div></div></div></section>
<div class="reading-strip"><div class="wrap"><span><b>01</b> Read the stories</span><span><b>02</b> Try the ideas</span><span><b>03</b> Follow the evidence</span></div></div>
<section class="section wrap" id="books"><div class="section-heading"><div><p class="eyebrow">Books by Paul Clark</p><h2>The bookshelf.</h2></div><p>For readers who want to know<br>what lies behind the message.</p></div>{BOOK_CARD}<div class="shelf-note"><span class="small-label">An open-ended collection</span><p>A home for this book and the ones still to come. New titles and publication news will be shared here as they are ready.</p><a class="text-link" href="/books/">Browse the bookshelf {arrow()}</a></div></section>
<section class="explore-section" id="explore"><div class="wrap"><div class="section-heading"><div><p class="eyebrow">Beyond the printed page</p><h2>The last page is<br>a beginning.</h2></div><p>Read about an idea. Try it yourself.<br>Then ask what the result really tells you.</p></div><div class="explore-grid"><a class="explore-card museum-card" href="https://ciphermuseum.com/"><div class="project-art"><img src="/assets/cipher-wheel.svg" width="300" height="220" alt="" loading="lazy"><span class="project-number">01 / THE HISTORY</span></div><div class="project-copy"><p class="eyebrow">A museum you can enter</p><h3>Cipher Museum {arrow(True)}</h3><p>Explore secret writing, historical codebreaking, and the people behind the discoveries. Follow an exhibit and try an idea for yourself.</p><span class="project-cta">Visit the free museum {arrow()}</span></div></a><a class="explore-card lab-card" href="https://crypto-lab.systemslibrarian.dev/"><div class="project-art"><img src="/assets/security-lattice.svg" width="300" height="220" alt="" loading="lazy"><span class="project-number">02 / THE EXPERIMENTS</span></div><div class="project-copy"><p class="eyebrow">An idea you can test</p><h3>Crypto Lab {arrow(True)}</h3><p>Experiment with encryption, signatures, privacy, and post-quantum cryptography through browser-based teaching demonstrations.</p><span class="project-cta">Explore the free labs {arrow()}</span></div></a></div><p class="explore-footnote">Both projects are free to explore. Teaching examples explain their assumptions and limits.</p></div></section>
<section class="section wrap author-intro"><div class="author-card" aria-label="Paul Clark, librarian, author, and educator"><p class="small-label">From the author’s desk</p><div class="author-monogram" aria-hidden="true">PC<span>✦</span></div><div class="author-card-bottom"><span>Paul Clark</span><small>Librarianship · Technology · Public service</small></div></div><div class="author-intro-copy"><p class="eyebrow">The person behind the pages</p><h2>A librarian’s curiosity.<br>A life of service.</h2><p>I’m Paul Clark. After three decades in library technology, I’m still drawn to the same question: how can we make difficult ideas useful and accessible to the people who need them?</p><p>My books, Cipher Museum, and Crypto Lab bring that question to cryptography—with attention to the sources, space to experiment, and care for the people behind the systems.</p><a class="text-link" href="/about/">More about Paul {arrow()}</a></div></section>
{contact()}'''

BOOKS = f'''<section class="page-intro wrap"><p class="eyebrow">The Cipher Librarian / Books</p><h1>Stories worth<br><em>opening.</em></h1><p class="intro-lead">Books about hidden messages, the people who read them, and the ideas that continue to shape our privacy.</p></section><section class="wrap bookshelf-page">{BOOK_CARD}<div class="future-note"><span class="note-index">Next on the shelf</span><h2>There is more to explore.</h2><p>This is a growing collection. Future books will have their home here, alongside publication details, previews, and connections to the museum and labs.</p><a class="text-link" href="/#explore">Explore the ideas in the meantime {arrow()}</a></div></section>{contact()}'''

BOOK = f'''<section class="book-detail-hero wrap"><div class="book-detail-art"><a href="#opening" aria-label="Read an opening excerpt">{cover(eager=True)}</a><p>Forthcoming · Publication details to follow</p></div><div class="book-detail-copy"><a class="breadcrumb" href="/books/">← The bookshelf</a><p class="eyebrow"><span class="status-dot"></span> A forthcoming book by Paul “The Cipher Librarian” Clark</p><h1>Secrets of the<br>Cipher Museum</h1><p class="detail-subtitle">Stories of Hidden Messages<br>and the People Behind Them</p><p class="detail-promise">Discover how people learned to read other people’s secrets—and what happened when they did.</p><p>Then enter Cipher Museum and try the ideas yourself.</p><div class="actions"><a class="button" href="#opening">Read the opening {arrow()}</a><a class="text-link" href="https://ciphermuseum.com/the-book.html#chapter-visits">Find your chapter’s exhibit {arrow(True)}</a></div></div></section>
<div class="book-detail-strip"><div class="wrap"><span>20 true investigations</span><span>No mathematical background needed</span><span>A free museum to explore alongside</span></div></div>
<section class="section wrap book-overview"><div><p class="eyebrow">The stories behind the secrets</p><h2>A secret becomes readable.<br>What happens next?</h2></div><div class="prose"><p>Unidentified letters in a French archive restore a queen’s voice. A British admiral must reveal a German proposal without exposing his service’s access. A codebreaker reads a smuggler’s orders after the chance to intervene has passed.</p><p>Across twenty investigations, <em>Secrets of the Cipher Museum</em> follows hidden messages into the decisions they make possible—and the questions they leave unresolved. The recovery of Copiale in 2011, the Zodiac 340 cipher in 2020 and Mary Stuart’s letters in 2023 brings the story into the work of modern researchers.</p><p>Who can be trusted with a secret? What does a deciphered message actually prove? When should someone act on what they know—and what might that action expose?</p><p>Eight original diagrams and six documentary images make crucial ideas visible. Chapter links and QR codes lead into the free Cipher Museum, where you can compare readings, test an assumption and inspect what a published recovery establishes. The historical narrative is complete without a browser.</p></div></section>
<section class="case-section" id="featured-investigations"><div class="wrap"><div class="section-heading"><div><p class="eyebrow">A few doors along the way</p><h2>People. Messages.<br>Consequences.</h2></div><p>History is the investigation.<br>The cipher is where it begins.</p></div><div class="case-grid"><article><span class="case-index">I / ROYAL LETTERS</span><h3>The queen’s<br>other reader</h3><p>Follow the letter’s delivery route and consider where someone could copy it while it continued to its recipient.</p><a class="text-link" href="https://ciphermuseum.com/ciphers/babington.html#delivery-route">Trace the intercepted letter {arrow(True)}</a></article><article><span class="case-index">II / WARTIME INTELLIGENCE</span><h3>The telegram Britain<br>could not simply reveal</h3><p>Follow two coded versions of the telegram and consider what Britain could reveal without exposing its access.</p><a class="text-link" href="https://ciphermuseum.com/ciphers/zimmermann.html#message-routes">Compare the message routes {arrow(True)}</a></article><article><span class="case-index">III / AN UNSOLVED IDENTITY</span><h3>The message<br>and the murderer</h3><p>Replay part of the published Z340 solution, then compare its original spellings with editorial corrections. The replay does not identify the murderer.</p><a class="text-link" href="https://ciphermuseum.com/lab/decipherment-cases.html#z340">Inspect the published reading {arrow(True)}</a></article></div></div></section>
<section class="section wrap opening-section" id="opening"><div class="opening-label"><p class="eyebrow">An opening excerpt</p><span>Prologue</span></div><div class="opening-prose"><h2>The letters without a name</h2><p>The letters were in the catalog. Their author was missing.</p><p>Pages of cipher lay among manuscripts in the Bibliothèque nationale de France, near material concerning Italian affairs in the early sixteenth century. A catalog could bring a researcher to those pages. It could not tell the researcher whose words were hidden there.</p><p>George Lasry, Norbert Biermann and Satoshi Tomokiyo were looking for historical ciphers they might decipher—a computer scientist in Israel, a pianist and music professor in Berlin, and a patent specialist in Japan, hunting in their spare hours. The unfamiliar signs were enough to interest them. They began without a famous name to guide the search.</p><a class="text-link" href="https://ciphermuseum.com/the-book.html#sample">Continue the opening in Cipher Museum {arrow(True)}</a><p class="excerpt-credit">Prologue excerpt © 2026 Paul “The Cipher Librarian” Clark. Draws on Lasry, Biermann and Tomokiyo’s <a href="https://doi.org/10.1080/01611194.2022.2160677">2023 study of Mary Stuart’s recovered letters</a>. Chapter 20 follows the full recovery. Biographical details follow the <a href="https://newsroom.taylorandfrancisgroup.com/codebreakers-crack-secrets-of-mary-queen-of-scots-lost-letters/">publisher’s research announcement</a> and <a href="https://www.wgbh.org/news/2023-02-10/3-amateur-codebreakers-set-out-to-decrypt-old-letters-they-uncovered-royal-history">NPR’s interview reporting</a>; Biermann’s <a href="https://www.udk-berlin.de/person/norbert-biermann/">university biography</a> identifies his Berlin teaching role.</p></div></section>
<section class="mystery-section wrap"><div class="envelope-art" aria-hidden="true"><svg viewBox="0 0 300 200"><path d="M25 30h250v145H25zM25 30l125 90L275 30M25 175l84-79m166 79l-84-79"/><circle cx="150" cy="112" r="24"/><path d="M143 102h14v19h-14zM147 98v8m6-8v8"/></svg></div><div><p class="eyebrow">An optional extra investigation</p><h2>The Curator’s<br>Sealed Letter</h2><p>Four optional slips appear after chapters 1, 3, 14 and 17. Keep their answers on paper or in the museum’s optional notebook, then join them to open an original fictional investigation. Each slip has its own hints; you can also start the case directly.</p><p class="small-copy">The case and online clues are free to everyone. No purchase is required.</p><a class="button" href="https://ciphermuseum.com/sealed-letter.html">Open the reader’s mystery {arrow(True)}</a></div></section>
<section class="section wrap faq-section" id="book-questions"><div><p class="eyebrow">Before you begin</p><h2>A few questions.</h2></div><div class="faq-list"><details><summary>How does it sit alongside The Code Book and The Codebreakers?</summary><p>The question running through this book is what people could prove and do once they could read a secret. Mary Stuart’s correspondence frames the investigations, which reach the modern recoveries of Copiale, Z340 and her lost letters. Each chapter offers a related museum activity in reading, testing or judging evidence. Kahn and Singh are acknowledged predecessors in the notes.</p></details><details><summary>Am I reading history or solving a mystery?</summary><p>The prologue and twenty historical chapters are nonfiction, with sources and uncertainties identified. Four optional invented slips lead to The Curator’s Sealed Letter, a separate fictional case. You can enjoy the whole historical narrative without solving a puzzle.</p></details><details><summary>Do I need to know cryptography?</summary><p>No mathematical background is required. This is narrative history about people and hidden messages. The museum offers an optional way to explore the ideas further.</p></details><details><summary>When will the book be available?</summary><p>The book is forthcoming. A publication date, available editions, pricing, and purchase links will be added here when they are confirmed.</p></details><details><summary>Do I need to buy the book to visit the museum?</summary><p>No. Cipher Museum, its public book preview, and The Curator’s Sealed Letter are free to explore.</p></details><details><summary>Is there something for a reading group?</summary><p>Yes. The museum’s guide gives a suggested 30-minute session: read the historical opening, investigate a clearly labelled fictional case, and discuss what the records support. An optional 15-minute puzzle warm-up uses the four slips.</p><a class="text-link" href="https://ciphermuseum.com/the-book.html#reading-groups">See the reading-group guide {arrow(True)}</a></details></div></section>{contact()}'''

ABOUT = f'''<section class="page-intro wrap about-intro"><p class="eyebrow">The Cipher Librarian / About Paul</p><h1>Curiosity, put<br>to <em>good use.</em></h1><p class="intro-lead">I’m Paul Clark—a librarian, author, and systems analyst who believes difficult ideas should have an open door.</p></section><section class="wrap about-body"><aside class="about-sidebar"><div class="author-card"><p class="small-label">Librarian · Author · Educator</p><div class="author-monogram" aria-hidden="true">PC<span>✦</span></div><div class="author-card-bottom"><span>Paul Clark</span><small>The Cipher Librarian</small></div></div><a class="text-link" href="https://systemslibrarian.dev/">My work in library technology {arrow(True)}</a></aside><div class="prose about-prose"><p class="eyebrow">A librarian first</p><h2>Making room for<br>the next question.</h2><p>I’ve spent around thirty years working in library technology and public service. My work as an Application Systems Analyst at Leon County Public Library in Tallahassee brings together systems, security, and the everyday needs of the people who depend on them.</p><p>Libraries have taught me to value access, patient explanation, and the difference between finding an answer and knowing why it deserves our trust.</p><p>That is the spirit behind my books, Cipher Museum, and Crypto Lab. I want readers to meet the people behind cryptography, understand the questions they faced, and have a way to try an idea for themselves.</p><h2>Why “The Cipher Librarian”?</h2><p>The name brings two parts of my life together: librarianship and the study of hidden messages. It covers a long route—from historical letters and codebreaking to modern protocols, privacy, and post-quantum security.</p><p>Some of that journey is best told as a story. Some is best understood by changing an input, running an experiment, and looking carefully at what happens.</p><div class="faith-note"><p class="eyebrow">Faith & purpose</p><h2>Knowledge in service<br>to others.</h2><p>My Christian faith shapes the way I approach this work. I believe our gifts are meant to serve others, and I want the things I write and build to honor God.</p><p>For me, that means caring about the people behind a system, being honest about what the evidence supports, and making useful knowledge accessible.</p><blockquote>“Whatever you do, do it all for the glory of God.”<cite>1 Corinthians 10:31</cite></blockquote></div><h2>What you’ll find here</h2><p>A growing bookshelf, connections to free learning resources, and an invitation to stay curious. Whether you arrive for the history or the mathematics, I hope you leave with a better question—and somewhere to explore it.</p><a class="text-link" href="/books/">Start with the books {arrow()}</a></div></section>{contact()}'''

PRIVACY = f'''<section class="page-intro wrap"><p class="eyebrow">The Cipher Librarian / Privacy</p><h1>A simple site.<br>A clear <em>approach.</em></h1></section><section class="wrap legal-prose prose"><p>This author website provides book information and links to Paul Clark’s projects.</p><h2>What this site does</h2><p>The site does not include an email sign-up form, advertising trackers, or third-party analytics scripts. Fonts and images are served with the site. Site hosting may process standard request information, such as an IP address, for delivery and security.</p><h2>Contacting Paul</h2><p>Email links open your email application. Information you choose to send is handled through email. Please do not include confidential information in an initial inquiry.</p><h2>Other websites</h2><p>Links to Cipher Museum, Crypto Lab, and other resources take you to separate websites, which may have their own privacy practices.</p><p>For questions, email <a href="mailto:{EMAIL}">{EMAIL}</a>.</p><p class="small-copy">Last updated October 31, 2026.</p></section>'''

PAGES = [
 ('index.html','Paul Clark — The Cipher Librarian','Books and interactive explorations of cryptography by Paul Clark, from historical ciphers to post-quantum security.', HOME, '/', 'home',False),
 ('books/index.html','Books by Paul Clark — The Cipher Librarian','Discover Secrets of the Cipher Museum and future books by Paul Clark, The Cipher Librarian.',BOOKS,'/books/','books',False),
 ('books/secrets-of-the-cipher-museum/index.html','Secrets of the Cipher Museum — Paul “The Cipher Librarian” Clark','Twenty true investigations into hidden messages, contested evidence and the consequences of knowing. Read the modern archival opening and follow the clues in Cipher Museum.',BOOK,'/books/secrets-of-the-cipher-museum/','books',True),
 ('about/index.html','About Paul Clark — The Cipher Librarian','Meet Paul Clark, librarian, author, and creator of Cipher Museum and Crypto Lab. Curiosity, public service, and Christian faith guide his work.',ABOUT,'/about/','about',False),
 ('privacy/index.html','Privacy — The Cipher Librarian','How The Cipher Librarian author website handles privacy, contact links, and external resources.',PRIVACY,'/privacy/','home',False),
]
for target,title,desc,body,path,active,book in PAGES:
    p=DIST/target;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(page(title,desc,body,path,active,book).replace('<br>', ' <br>'))
not_found='<section class="page-intro wrap"><p class="eyebrow">Page not found</p><h1>A page out<br>of <em>place.</em></h1><p class="intro-lead">This address doesn’t lead to a page in the collection.</p><a class="button" href="/">Return to the beginning →</a></section>'
(DIST/'404.html').write_text(page('Page not found — The Cipher Librarian','Find your way back to the books and explorations of Paul Clark.',not_found))
(DIST/'robots.txt').write_text(f'User-agent: *\nAllow: /\nSitemap: {ORIGIN}/sitemap.xml\n')
(DIST/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>{ORIGIN+p[4]}</loc></url>' for p in PAGES)+'</urlset>')
print(f'Built {len(PAGES)} pages and a 404 page.')
